slides=[]
def slide(page,title,topic,paragraphs,eq=(),symbols='',case=None,subset=None,core=True):
 slides.append(dict(page=page,title=title,topic=topic,paragraphs=paragraphs,equations=list(eq),symbols=symbols,case=case,subset=subset,core=core))
slide(1,'Confidence intervals estimate population quantities','meaning',[
 'A confidence interval gives a range of population values compatible with a sample estimate and its uncertainty. Estimating the size of an effect answers a different question from deciding whether an effect differs from zero.',
 'The population quantity can be one mean, a difference between two means, one proportion, or a difference between two proportions. The center comes from the corresponding sample estimate, and the distance to each endpoint depends on its standard error.',
 'The confidence level specifies the coverage of the interval-producing procedure across repeated samples. The same interval can also support a hypothesis decision by checking whether it includes the population value specified by the null hypothesis.'
],core=False)
slide(2,'Two independent means and the pooled standard error','twoMeans',[
 r'The null hypothesis \(H_0:\mu_1=\mu_2\) states that the two population means are equal. The alternative \(H_A:\mu_1\ne\mu_2\) states that they differ. The sample difference \(\bar x_1-\bar x_2\) estimates the population difference \(\mu_1-\mu_2\).',
 r'The pooled two-sample method assumes independent observations from Normal populations with a common variance. The pooled variance \(s^2\) combines the two sample variances, weighting each by its sample degrees of freedom. Squaring each SD produces the variance needed in that calculation.',
 r'The standard error describes the variability of the difference between sample means. Dividing the observed difference by this standard error gives the test statistic under a zero-difference null. The degrees of freedom are \(\nu=n_1+n_2-2\), and a two-sided test compares the magnitude of the statistic with the positive course-table cutoff.'
],[r'H_0:\mu_1=\mu_2,\qquad H_A:\mu_1\ne\mu_2',r's^2=\frac{(n_1-1)s_1^2+(n_2-1)s_2^2}{n_1+n_2-2}',r's_{\bar x_1-\bar x_2}=\sqrt{\frac{s^2}{n_1}+\frac{s^2}{n_2}}',r't=\frac{\bar x_1-\bar x_2}{s_{\bar x_1-\bar x_2}},\qquad \nu=n_1+n_2-2'],r'\(\bar x_i\) (group sample mean), \(s_i\) (group sample SD), \(n_i\) (group sample size), \(s^2\) (pooled variance), \(\nu\) (degrees of freedom).')
slide(3,'The middle 95% of the t distribution','meaning',[
 r'Under the equal-means null hypothesis, the standardized sample difference follows the central \(t\) distribution with the appropriate degrees of freedom. Positive and negative values represent opposite directions of the observed difference.',
 r'The middle 95% lies between a negative and a positive critical value. A total of 5% remains outside this range, split into 2.5% in each tail. A two-sided comparison uses both extremes rather than treating the full 5% as one tail.',
 r'The course notation \(t_{0.05}(\nu)\) denotes the positive cutoff in the total two-tail 0.05 column. Its cumulative probability is 0.975. The degrees of freedom determine which row supplies the cutoff.'
],[r'P\!\left(-t_{0.05}(\nu)<T_\nu<t_{0.05}(\nu)\right)=0.95'],r'\(T_\nu\) (random t statistic), \(t_{0.05}(\nu)\) (positive critical value with 0.05 total outside both tails).',core=False)
slide(4,'Rearranging the t statement into a mean-difference interval','twoMeans',[
 r'For a population difference that can be nonzero, the numerator compares the observed difference with the true difference. Write \(d=\bar x_1-\bar x_2\), \(\Delta=\mu_1-\mu_2\), and \(SE=s_{\bar x_1-\bar x_2}\). Then the standardized quantity is \((d-\Delta)/SE\).',
 'Multiply the central t inequality by the positive standard error. Subtract the observed difference from all three parts. Multiplying by minus one reverses both inequality directions, and writing the smaller endpoint on the left puts the population difference between the two bounds.',
 'The resulting interval is centered on the observed difference. The critical value multiplied by the standard error is the margin of error. Adding and subtracting the same margin gives the upper and lower endpoints.'
],[r'-t_c<\frac{d-\Delta}{SE}<t_c',r'-t_cSE<d-\Delta<t_cSE',r'-t_cSE-d<-\Delta<t_cSE-d',r'd-t_cSE<\Delta<d+t_cSE'],r'\(d\) (sample difference), \(\Delta\) (population difference), \(SE\) (standard error), \(t_c\) (positive two-sided t cutoff).')
slide(5,'General confidence interval for a difference of means','twoMeans',[
 r'A \(100(1-\alpha)\%\) confidence interval for \(\mu_1-\mu_2\) has center \(\bar x_1-\bar x_2\). Choose the subtraction order before calculating and keep that same order in the numerical difference and population interpretation.',
 r'The margin of error is \(t_\alpha(\nu)\) multiplied by the pooled standard error of the difference. The course table uses total two-tail \(\alpha\). Increasing the confidence level uses a more extreme cutoff and gives a wider interval for the same data.',
 'A positive interval places the first population mean above the second. A negative interval places it below the second. An interval spanning zero includes equal population means among its compatible values.'
],[r'd=\bar x_1-\bar x_2,\qquad M=t_\alpha(\nu)s_{\bar x_1-\bar x_2}',r'L=d-M,\qquad U=d+M',r'(\bar x_1-\bar x_2)-t_\alpha(\nu)s_{\bar x_1-\bar x_2}<\mu_1-\mu_2<(\bar x_1-\bar x_2)+t_\alpha(\nu)s_{\bar x_1-\bar x_2}'],r'\(L,U\) (interval endpoints), \(M\) (margin of error), \(\alpha\) (total probability outside the central interval).')
slide(6,'Urine production with a diuretic versus placebo','twoMeans',[
 r'The diuretic group has a mean urine production of 1,400 mL/day and an SD of 245 mL/day. The placebo group has a mean of 1,180 mL/day and an SD of 144 mL/day. Each group has ten observations, and the requested direction is diuretic minus placebo.',
 r'The observed mean difference is 220 mL/day. Pooling the sample variances gives a common variance estimate, and dividing its contribution across the two group sizes gives the standard error of the difference. The degrees of freedom are 18.',
 'The 95% interval is approximately 31 to 409 mL/day. Both endpoints are positive, so the compatible population differences favor greater urine production with the diuretic. The interval estimates the difference between population means in mL/day.'
],case='ci-urine')
slide(7,'Repeated-sampling meaning of 95% confidence','meaning',[
 'Different random samples produce different sample estimates, standard errors, and interval endpoints. A 95% confidence procedure produces intervals containing the true population quantity in 95% of repeated applications under its assumptions. Some of the intervals miss that same fixed population quantity.',
 'The population difference remains fixed while the sampled data and the resulting interval change. Before sampling, the constructed interval is random. The lecture’s probability wording concerns this interval-generating process and its long-run coverage.',
 'For an observed interval, 95% confidence describes the procedure used to calculate its bounds. The endpoints estimate a population mean or difference, rather than enclosing 95% of individual observations. Confidence in a mean difference and variability among individual people describe different quantities.'
],[r'\text{confidence level}=100(1-\alpha)\%'])
slide(8,'Testing a zero-difference null using its interval','decision',[
 r'For a two-sided comparison of two population means, \(H_0:\mu_1-\mu_2=0\) states that the means are equal. The alternative \(H_A:\mu_1-\mu_2\ne0\) states that they differ. Zero is the null value for this difference.',
 r'If the matching \(100(1-\alpha)\%\) interval includes zero, do not reject the equal-means null at significance level \(\alpha\). The observed difference is compatible with a population difference of zero under that interval procedure.',
 r'If the interval excludes zero, reject the equal-means null for the matching two-sided test. An entirely positive interval supports the first mean being higher, while an entirely negative interval supports it being lower. The confidence level, method, and subtraction order have to match the test being interpreted.'
],[r'L\le0\le U\ \Longrightarrow\ \text{do not reject }H_0',r'L>0\ \text{or}\ U<0\ \Longrightarrow\ \text{reject }H_0'],r'\(L,U\) (bounds for the population difference). For a single mean or proportion, compare the interval with its specified null value instead of automatically using zero.')
slide(9,'Confidence interval for one population mean','oneMean',[
 r'A sample mean \(\bar x\) estimates a population mean \(\mu\). With sample SD \(s\) and sample size \(n\), the standard error is \(s_{\bar x}=s/\sqrt n\). This is uncertainty in the estimated mean, whereas the SD describes spread among individual observations.',
 r'The one-sample t procedure has \(\nu=n-1\) degrees of freedom. The interval extends a critical number of standard errors below and above the sample mean. Larger samples reduce the standard error for a fixed SD.',
 r'For a reference mean \(\mu_0\), \(H_0:\mu=\mu_0\) means that the population mean equals that reference. \(H_A:\mu\ne\mu_0\) means it differs. A matching two-sided decision checks whether \(\mu_0\) is included in the interval.'
],[r's_{\bar x}=\frac{s}{\sqrt n},\qquad \nu=n-1',r'\bar x-t_\alpha(\nu)\frac{s}{\sqrt n}<\mu<\bar x+t_\alpha(\nu)\frac{s}{\sqrt n}'],r'\(\bar x\) (sample mean), \(s\) (sample SD), \(n\) (sample size), \(\mu\) (population mean), \(\mu_0\) (null reference mean).')
slide(10,'Mean heart rate for BME423 students','oneMean',[
 r'Ten BME423 students have a sample mean heart rate of 67 beats/min and a sample SD of 9 beats/min. The population quantity is the mean heart rate for BME423 students, rather than the heart rate of a particular student.',
 r'The standard error is \(9/\sqrt{10}\), approximately 2.85 beats/min, and the degrees of freedom are nine. The positive t cutoff in the total two-tail 0.05 column is approximately 2.262. Multiplying the cutoff by the standard error gives a margin near 6.44 beats/min.',
 'Subtracting and adding the margin gives approximately 60.6 to 73.4 beats/min. This interval estimates the population mean. The SD remains the measure of variation among individual heart rates.'
],case='ci-heart')
slide(11,'Difference of two proportions using the course pooled SE','twoProportions',[
 r'For two groups with event counts \(m_1,m_2\) and sample sizes \(n_1,n_2\), the sample proportions are \(\hat p_1=m_1/n_1\) and \(\hat p_2=m_2/n_2\). Their difference estimates \(p_1-p_2\), the population difference in event probabilities.',
 r'This lecture uses a pooled estimate \(\hat p=(m_1+m_2)/(n_1+n_2)\). Its binary variance is \(\hat p(1-\hat p)\), and the standard error of the difference uses this pooled variance divided by each group size. The same lecture convention is used in the calculations here.',
 r'The Normal critical value \(z_\alpha\) gives the central confidence interval. For 95% confidence it is 1.96, equivalent to the infinite-df row of the two-tail t table. Multiply it by the standard error, then subtract and add that margin to the observed proportion difference.'
],[r'\hat p_i=\frac{m_i}{n_i},\qquad \hat p=\frac{m_1+m_2}{n_1+n_2}',r's^2=\hat p(1-\hat p),\qquad s_{\hat p_1-\hat p_2}=\sqrt{\frac{s^2}{n_1}+\frac{s^2}{n_2}}',r'(\hat p_1-\hat p_2)-z_\alpha s_{\hat p_1-\hat p_2}<p_1-p_2<(\hat p_1-\hat p_2)+z_\alpha s_{\hat p_1-\hat p_2}'],r'\(m_i\) (event count), \(n_i\) (group size), \(\hat p_i\) (group sample proportion), \(\hat p\) (pooled proportion), \(p_i\) (population proportion).')
slide(12,'Thrombosis with placebo versus aspirin','twoProportions',[
 r'Thrombosis occurs in 18 of 25 placebo patients and six of 19 aspirin patients. The subtraction order is placebo minus aspirin. The slide rounds the proportions to 0.72 and 0.32 and supplies a rounded standard error of 0.15.',
 r'Following those displayed rounded values gives a difference of 0.40 and a margin \(1.96(0.15)=0.294\). The endpoints are 0.106 and 0.694, displayed in the lecture as approximately 0.11 and 0.69.',
 'The result is an absolute difference of approximately 11 to 69 percentage points in event probability, favoring aspirin. It is not a relative-risk reduction. Keeping the original fractions and more intermediate digits produces slightly different endpoints because the slide rounds early.'
],case='ci-aspirin')
slide(13,'Confidence interval for a population proportion','oneProportion',[
 r'For one sample with \(m\) events among \(n\) observations, \(\hat p=m/n\) estimates the population event proportion \(p\). The estimated standard error is the square root of \(\hat p(1-\hat p)/n\).',
 r'The confidence interval has center \(\hat p\) and margin \(z_\alpha s_{\hat p}\). The lower and upper limits are proportions. Multiplying a proportion by 100 expresses the same quantity as a percentage.',
 r'For a specified reference \(p_0\), \(H_0:p=p_0\) says that the population proportion equals that reference. \(H_A:p\ne p_0\) says it differs. The matching two-sided interval decision checks whether the particular \(p_0\) is included.'
],[r'\hat p=\frac{m}{n},\qquad s_{\hat p}=\sqrt{\frac{\hat p(1-\hat p)}{n}}',r'\hat p-z_\alpha s_{\hat p}<p<\hat p+z_\alpha s_{\hat p}'],r'\(m\) (event count), \(n\) (sample size), \(\hat p\) (sample proportion), \(p\) (population proportion), \(p_0\) (null reference).')
slide(14,'Stimulant survey estimate, SE, and critical value','oneProportion',[
 r'Among 500 responding college students, 177 report taking a non-prescribed stimulant during the past year. The sample proportion is \(177/500=0.354\). The population quantity is the proportion reporting this behavior in the population being studied.',
 r'Compute the estimated binary variance as \(0.354(1-0.354)\), divide by 500, and take the square root. The resulting standard error is approximately 0.021386. Keeping the square root is essential because the variance and standard error are different quantities.',
 r'The question asks whether the population proportion differs from 0.5. The null means half of the population, and the two-sided alternative means a proportion other than half. For a 95% interval, the Normal cutoff is 1.96, read from the infinite-df row of the total two-tail 0.05 t-table column.'
],case='ci-survey',subset=[0,4])
slide(15,'Survey interval and decision about one half','oneProportion',[
 r'The survey estimate is 0.354 and its standard error is approximately 0.021386. The 95% margin is \(1.96\) times that standard error. Subtracting and adding the margin gives the two endpoints around the same estimate.',
 r'The resulting interval is approximately \(0.312<p<0.396\), or 31.2% to 39.6%. These bounds describe the estimated population proportion reporting nonmedical stimulant use during the specified year.',
 r'The interval does not include 0.5, and both endpoints are below it. Reject \(H_0:p=0.5\) for the matching two-sided 0.05 comparison. In words, the data support a population proportion different from, and below, one half.'
],case='ci-survey',subset=[4,8])
slide(16,'One-proportion interval and its null reference','oneProportion',[
 r'The population proportion \(p\) is estimated by \(\hat p\), and the uncertainty is measured using \(s_{\hat p}=\sqrt{\hat p(1-\hat p)/n}\). The same interval structure uses the sample estimate as its center and a critical multiple of the standard error as its margin.',
 r'The null hypothesis is \(H_0:p=p_0\). Its meaning depends on the stated reference \(p_0\), so the decision concerns that value. For a reference of one half, the comparison is with 0.5 rather than with zero.',
 'An interval entirely below the reference supports a smaller population proportion, while an interval entirely above it supports a larger one. If the reference is included, the matching two-sided comparison does not reject that null value.'
],[r'\hat p-z_\alpha\sqrt{\frac{\hat p(1-\hat p)}{n}}<p<\hat p+z_\alpha\sqrt{\frac{\hat p(1-\hat p)}{n}}'],r'\(\hat p\) (sample proportion), \(p\) (population proportion), \(p_0\) (value specified by the null), \(n\) (sample size).',core=False)
slide(17,'Glucose lecture exercise, solved through the interval','twoMeans',[
 r'A trial of 1,700 pre-diabetic participants compares placebo with a glucose-lowering drug. Each group has 850 participants. The placebo sample mean and SD are 112.4 and 4.7 mg/dL, while the drug mean and SD are 109.1 and 3.9 mg/dL.',
 r'Define the difference as placebo minus drug, giving an observed 3.3 mg/dL difference. The pooled variance is 18.65, the degrees of freedom are 1,698, and the standard error is approximately 0.209481 mg/dL. The positive 95% t cutoff is approximately 1.961362.',
 r'The interval is approximately 2.889 to 3.711 mg/dL. Zero is outside the interval, so reject equal population means at the matching two-sided 0.05 level without separately calculating a t statistic. The positive direction supports lower population mean glucose in the drug group.'
],case='ci-glucose')
cases=[]
def step(title,general,work,words): return dict(title=title,general=general if isinstance(general,list) else [general],work=work if isinstance(work,list) else [work],words=words)
def finish_case(c):
 c['module']=17;c['tolerance']=0.002;c['answerName']='Lower endpoint';c['answer']=c['values']['lower'];cases.append(c);return c

def mean_case(id,title,context,n,x,sd,confidence=.95,source=None,reference=None):
 alpha=1-confidence;df=n-1;se=sd/math.sqrt(n);tc=float(stats.t.ppf(1-alpha/2,df));margin=tc*se;lo=x-margin;hi=x+margin
 steps=[
 step('Identify the population quantity',r'\text{estimate of }\mu=\bar x',rf'\bar x={f(x)},\quad s={f(sd)},\quad n={n}', 'The sample mean estimates the population mean. The SD describes individual measurements; the standard error describes uncertainty in their mean.'),
 step('Calculate the standard error',r's_{\bar x}=\frac{s}{\sqrt n}',rf's_{{\bar x}}=\frac{{{f(sd)}}}{{\sqrt{{{n}}}}}=\frac{{{f(sd)}}}{{{f(math.sqrt(n))}}}={f(se)}','Divide the sample SD by the square root of sample size. Keep the standard error available for the margin calculation.'),
 step('Choose degrees of freedom and the cutoff',[r'\nu=n-1',r't_c=t_\alpha(\nu)'],[rf'\nu={n}-1={df}',rf'\alpha=1-{f(confidence)}={f(alpha)},\quad t_{{{f(alpha)}}}({df})={f(tc)}'],f'Use the t-table row for {df} degrees of freedom and the total two-tail {f(alpha)} column. On a TI-84, invT({f(1-alpha/2)},{df}) returns the positive cutoff.'),
 step('Calculate the margin of error',r'M=t_c s_{\bar x}',rf'M={f(tc)}({f(se)})={f(margin)}','The margin has the same measurement units as the sample mean.'),
 step('Calculate the lower endpoint',r'L=\bar x-M',rf'L={f(x)}-{f(margin)}={f(lo)}','Subtract the margin from the sample mean.'),
 step('Calculate the upper endpoint',r'U=\bar x+M',rf'U={f(x)}+{f(margin)}={f(hi)}','Add the same margin to the sample mean.'),
 step('State the population interval',r'L<\mu<U',rf'{f(lo)}<\mu<{f(hi)}',f'The {100*confidence:g}% interval estimates the population mean in the original measurement units. It is not an interval containing this percentage of individual measurements.')]
 conclusion=f'The {100*confidence:g}% confidence interval for the population mean is {f(lo)} to {f(hi)} {context["unit"]}.'
 return finish_case(dict(id=id,title=title,topic='oneMean',context=context['text'],unit=context['unit'],table={'headers':['Sample size','Sample mean','Sample SD'],'rows':[[n,x,sd]]},tasks=[f'Construct a {100*confidence:g}% confidence interval for the population mean. Show the standard error, degrees of freedom, critical value, margin, and both endpoints.','Interpret the interval in the measurement units and distinguish it from individual variation.'],symbols=r'\(\bar x\) (sample mean), \(s\) (sample SD), \(n\) (number sampled), \(s_{\bar x}\) (standard error of the mean), \(\mu\) (population mean), \(M\) (margin).',steps=steps,conclusion=conclusion,source=source,values=dict(n=n,x=x,sd=sd,confidence=confidence,df=df,se=se,critical=tc,margin=margin,lower=lo,upper=hi)))

def two_mean_case(id,title,context,n1,x1,s1,n2,x2,s2,labels,unit,confidence=.95,source=None):
 df=n1+n2-2;var=((n1-1)*s1*s1+(n2-1)*s2*s2)/df;se=math.sqrt(var/n1+var/n2);tc=float(stats.t.ppf((1+confidence)/2,df));d=x1-x2;margin=tc*se;lo=d-margin;hi=d+margin;alpha=1-confidence
 a,b=labels;direction=f'{a} minus {b}';reject=lo>0 or hi<0
 hyp={'null':r'H_0:\mu_1-\mu_2=0','alternative':r'H_A:\mu_1-\mu_2\ne0','nullWords':f'The {a} and {b} populations have equal means.','alternativeWords':f'The {a} and {b} population means differ.'}
 steps=[
 step('Define the contrast and hypotheses',r'\Delta=\mu_1-\mu_2',rf'\Delta=\mu_{{\mathrm{{{a}}}}}-\mu_{{\mathrm{{{b}}}}}',f'Keep the direction {direction} throughout. The null means equal population means; the two-sided alternative means different population means.'),
 step('Calculate the observed difference',r'd=\bar x_1-\bar x_2',rf'd={f(x1)}-{f(x2)}={f(d)}',f'This is the sample estimate of the population difference in {unit}.'),
 step('Square both group SDs',[r'v_1=s_1^2',r'v_2=s_2^2'],[rf'v_1={f(s1)}^2={f(s1*s1)}',rf'v_2={f(s2)}^2={f(s2*s2)}'],'Each SD is squared before pooling, giving variances in squared measurement units.'),
 step('Pool both variance contributions',r's^2=\frac{(n_1-1)s_1^2+(n_2-1)s_2^2}{n_1+n_2-2}',[rf'(n_1-1)s_1^2=({n1}-1)({f(s1*s1)})={f((n1-1)*s1*s1)}',rf'(n_2-1)s_2^2=({n2}-1)({f(s2*s2)})={f((n2-1)*s2*s2)}',rf's^2=\frac{{{f((n1-1)*s1*s1)}+{f((n2-1)*s2*s2)}}}{{{n1}+{n2}-2}}=\frac{{{f((n1-1)*s1*s1+(n2-1)*s2*s2)}}}{{{df}}}={f(var)}'],'Weight each group variance by its own degrees of freedom, add the contributions, and divide by the combined degrees of freedom.'),
 step('Calculate the SE of the difference',r's_d=\sqrt{\frac{s^2}{n_1}+\frac{s^2}{n_2}}',rf's_d=\sqrt{{\frac{{{f(var)}}}{{{n1}}}+\frac{{{f(var)}}}{{{n2}}}}}=\sqrt{{{f(var/n1+var/n2)}}}={f(se)}','Add the two mean-variance contributions inside the root, then take the root. This restores the original measurement units.'),
 step('Find degrees of freedom and the t cutoff',[r'\nu=n_1+n_2-2',r't_c=t_\alpha(\nu)'],[rf'\nu={n1}+{n2}-2={df}',rf'\alpha=1-{f(confidence)}={f(alpha)},\quad t_{{{f(alpha)}}}({df})={f(tc)}'],f'The table uses total two-tail alpha. For an exact cutoff, TI-84 invT({f((1+confidence)/2)},{df}) uses the left cumulative area.'),
 step('Calculate the margin',r'M=t_c s_d',rf'M={f(tc)}({f(se)})={f(margin)}','Multiply the positive cutoff by the standard error of the difference.'),
 step('Calculate both bounds',[r'L=d-M',r'U=d+M'],[rf'L={f(d)}-{f(margin)}={f(lo)}',rf'U={f(d)}+{f(margin)}={f(hi)}'],f'The bounds retain the {direction} subtraction order.'),
 step('Make the decision using the interval',r'0\notin[L,U]\Rightarrow\text{reject }H_0' if reject else r'0\in[L,U]\Rightarrow\text{do not reject }H_0',rf'[{f(lo)},{f(hi)}]',f'{"Zero is outside" if reject else "Zero is inside"} the interval. {"Reject" if reject else "Do not reject"} the equal-means null at the matching two-sided {f(alpha)} level; no separate t statistic is required.')]
 conclusion=f'The {100*confidence:g}% CI for {direction} is {f(lo)} to {f(hi)} {unit}. '+(f'The population means differ, with {a} higher.' if lo>0 else f'The population means differ, with {a} lower.' if hi<0 else 'The interval includes equal population means, so the comparison does not reject equality.')
 return finish_case(dict(id=id,title=title,topic='twoMeans',context=context+' Assume independent Normal responses with a common population variance.',unit=unit,table={'headers':['Group','Sample size','Mean','SD'],'rows':[[a,n1,x1,s1],[b,n2,x2,s2]]},tasks=[f'Construct the {100*confidence:g}% confidence interval for the population difference, {direction}. Show both variance contributions, the pooled variance, SE, df, critical value, margin, and both bounds.',f'Using the interval alone, decide whether the means differ at the matching two-sided {f(alpha)} level. State both hypotheses in symbols and words, and conclude in context.'],hypotheses=hyp,symbols=r'\(\bar x_i\) (group sample mean), \(s_i\) (group sample SD), \(n_i\) (group sample size), \(s^2\) (pooled variance), \(s_d\) (SE of the difference), \(d\) (sample difference), \(\Delta\) (population difference).',steps=steps,conclusion=conclusion,source=source,values=dict(n1=n1,n2=n2,x1=x1,x2=x2,s1=s1,s2=s2,confidence=confidence,df=df,variance=var,se=se,critical=tc,difference=d,margin=margin,lower=lo,upper=hi,reject=reject)))

def prop_case(id,title,context,m,n,confidence=.95,reference=.5,source=None):
 p=m/n;v=p*(1-p);se=math.sqrt(v/n);zc=1.96 if confidence==.95 else float(stats.norm.ppf((1+confidence)/2));margin=zc*se;lo=p-margin;hi=p+margin;reject=not(lo<=reference<=hi)
 steps=[step('State the proportion and hypotheses',r'H_0:p=p_0,\qquad H_A:p\ne p_0',rf'p_0={f(reference)}',f'The null states that the population event proportion is {reference:g}. The two-sided alternative states that it differs from {reference:g}.'),step('Calculate the sample proportion',r'\hat p=\frac{m}{n}',rf'\hat p=\frac{{{m}}}{{{n}}}={f(p)}','Divide event count by the total number of observations.'),step('Calculate the proportion SE',r's_{\hat p}=\sqrt{\frac{\hat p(1-\hat p)}{n}}',[rf'\hat p(1-\hat p)={f(p)}(1-{f(p)})={f(v)}',rf's_{{\hat p}}=\sqrt{{\frac{{{f(v)}}}{{{n}}}}}=\sqrt{{{f(v/n)}}}={f(se)}'],'Subtract the proportion from one, multiply, divide by sample size, then take the square root.'),step('Select the Normal cutoff',r'z_c=z_\alpha',rf'\alpha=1-{f(confidence)}={f(1-confidence)},\quad z_c={f(zc)}',f'Use the infinite-df row of the course two-tail t table. For {100*confidence:g}% confidence, the positive cutoff is {f(zc)}.'),step('Calculate the margin',r'M=z_c s_{\hat p}',rf'M={f(zc)}({f(se)})={f(margin)}','The margin is in proportion units. Multiply by 100 only when converting the final interpretation to percentage points.'),step('Calculate the lower bound',r'L=\hat p-M',rf'L={f(p)}-{f(margin)}={f(lo)}','Subtract the margin from the observed proportion.'),step('Calculate the upper bound',r'U=\hat p+M',rf'U={f(p)}+{f(margin)}={f(hi)}','Add the same margin to the observed proportion.'),step('Compare with the null reference',r'p_0\notin[L,U]\Rightarrow\text{reject }H_0' if reject else r'p_0\in[L,U]\Rightarrow\text{do not reject }H_0',rf'{f(lo)}<p<{f(hi)},\quad p_0={f(reference)}',f'{"Reject" if reject else "Do not reject"} equality with {reference:g} at the matching two-sided {1-confidence:g} level. The comparison is with the stated reference, not automatically with zero.')]
 return finish_case(dict(id=id,title=title,topic='oneProportion',context=context,unit='proportion',table={'headers':['Event count','Total observations','Reference proportion'],'rows':[[m,n,reference]]},tasks=[f'Construct a {100*confidence:g}% CI for the population proportion. Show the estimate, standard error, cutoff, margin, and both bounds.',f'Determine whether the population proportion differs from {reference:g} using the interval. State the hypotheses in symbols and words and interpret the result.'],hypotheses={'null':rf'H_0:p={f(reference)}','alternative':rf'H_A:p\ne {f(reference)}','nullWords':f'The population event proportion equals {reference:g}.','alternativeWords':f'The population event proportion differs from {reference:g}.'},symbols=r'\(m\) (event count), \(n\) (sample size), \(\hat p\) (sample event proportion), \(p\) (population event proportion), \(p_0\) (null reference), \(s_{\hat p}\) (estimated SE).',steps=steps,conclusion=f'The {100*confidence:g}% CI is {f(lo)} to {f(hi)}, or {lo*100:.2f}% to {hi*100:.2f}%. '+('The reference is excluded; the data support a different population proportion.' if reject else 'The reference is included; the data do not reject that population proportion.'),source=source,values=dict(m=m,n=n,p=p,reference=reference,confidence=confidence,variance=v,se=se,critical=zc,margin=margin,lower=lo,upper=hi,reject=reject)))

def two_prop_case(id,title,context,m1,n1,m2,n2,labels=('group1','group2'),source=None,rounded=False):
 raw1=m1/n1;raw2=m2/n2;p=(m1+m2)/(n1+n2);v=p*(1-p);rawse=math.sqrt(v/n1+v/n2);p1=round(raw1,2) if rounded else raw1;p2=round(raw2,2) if rounded else raw2;se=round(rawse,2) if rounded else rawse;d=p1-p2;zc=1.96;margin=zc*se;lo=d-margin;hi=d+margin;reject=not(lo<=0<=hi);a,b=labels
 steps=[step('Define the population difference',r'\Delta=p_1-p_2',rf'\Delta=p_{{\mathrm{{{a}}}}}-p_{{\mathrm{{{b}}}}}',f'Use {a} minus {b}. Equal population event probabilities correspond to a difference of zero.'),step('Calculate both sample proportions',r'\hat p_i=\frac{m_i}{n_i}',[rf'\hat p_1=\frac{{{m1}}}{{{n1}}}={f(raw1)}'+(rf'\approx {f(p1)}' if rounded else ''),rf'\hat p_2=\frac{{{m2}}}{{{n2}}}={f(raw2)}'+(rf'\approx {f(p2)}' if rounded else '')],'Each event count is divided by its own group size.'),step('Calculate the course pooled proportion',r'\hat p=\frac{m_1+m_2}{n_1+n_2}',rf'\hat p=\frac{{{m1}+{m2}}}{{{n1}+{n2}}}=\frac{{{m1+m2}}}{{{n1+n2}}}={f(p)}','Combine event counts and group sizes before taking the fraction. This follows the Session 17 pooled convention.'),step('Calculate the pooled binary variance',r's^2=\hat p(1-\hat p)',rf's^2={f(p)}(1-{f(p)})={f(v)}','The pooled binary variance is used in both group contributions to the SE.'),step('Calculate the difference SE',r's_d=\sqrt{\frac{s^2}{n_1}+\frac{s^2}{n_2}}',rf's_d=\sqrt{{\frac{{{f(v)}}}{{{n1}}}+\frac{{{f(v)}}}{{{n2}}}}}={f(rawse)}'+(rf'\approx {f(se)}' if rounded else ''),'Keep the two group sizes separate inside the square root.'+(' The lecture example uses the displayed rounded SE of 0.15 for its interval.' if rounded else '')),step('Calculate the difference and margin',[r'd=\hat p_1-\hat p_2',r'M=z_{0.05}s_d'],[rf'd={f(p1)}-{f(p2)}={f(d)}',rf'M=1.96({f(se)})={f(margin)}'],'Use the Normal cutoff 1.96 from the infinite-df row, total two-tail 0.05 column.'+(' This reproduces the slide’s early-rounded arithmetic.' if rounded else '')),step('Calculate both endpoints',[r'L=d-M',r'U=d+M'],[rf'L={f(d)}-{f(margin)}={f(lo)}',rf'U={f(d)}+{f(margin)}={f(hi)}'],'These are absolute differences of event probabilities. Multiply by 100 to express the difference in percentage points.'),step('Interpret direction and the zero comparison',r'0\notin[L,U]\Rightarrow\text{reject equal proportions}' if reject else r'0\in[L,U]\Rightarrow\text{do not reject equal proportions}',rf'{f(lo)}<p_1-p_2<{f(hi)}',f'The interval {"excludes" if reject else "includes"} zero. Retain the {a} minus {b} order when stating which event probability is higher.')]
 return finish_case(dict(id=id,title=title,topic='twoProportions',context=context,unit='proportion difference',table={'headers':['Group','Events','Total observations'],'rows':[[a,m1,n1],[b,m2,n2]]},tasks=['Construct the 95% confidence interval for the difference in population event proportions using the Session 17 pooled standard error. Show both sample proportions, the pooled estimate, variance, SE, margin, and endpoints.','Use the interval to decide whether the event probabilities differ at the matching two-sided 0.05 level. Interpret the direction and distinguish percentage points from a relative reduction.'],hypotheses={'null':r'H_0:p_1-p_2=0','alternative':r'H_A:p_1-p_2\ne0','nullWords':f'The {a} and {b} populations have equal event probabilities.','alternativeWords':f'The {a} and {b} population event probabilities differ.'},symbols=r'\(m_i\) (group event count), \(n_i\) (group size), \(\hat p_i\) (group sample proportion), \(\hat p\) (pooled estimate), \(s_d\) (SE of the difference), \(d\) (observed difference).',steps=steps,conclusion=f'The 95% interval for {a} minus {b} is {f(lo)} to {f(hi)}, equivalent to {100*lo:.2f} to {100*hi:.2f} percentage points. '+('Equal event probabilities are excluded.' if reject else 'Equal event probabilities remain included.'),source=source,rounded=rounded,values=dict(m1=m1,n1=n1,m2=m2,n2=n2,p1=p1,p2=p2,pooled=p,variance=v,se=se,rawSE=rawse,difference=d,critical=zc,confidence=.95,margin=margin,lower=lo,upper=hi,reject=reject)))

