methods=[
 dict(id='meaning',title='Interpret the confidence level',trigger='A question asks what 95% confidence means or what an interval estimates.',pages=[3,7],formula=[r'\text{confidence}=100(1-\alpha)\%'],example='ci-heart',shortcut='Identify the fixed population quantity and the varying sample interval. State long-run coverage of the interval procedure.'),
 dict(id='twoMeans',title='Two independent means → pooled t interval',trigger='Two independent groups have means, SDs, and sample sizes; estimate their population mean difference.',pages=[2,4,5,6,17],formula=[r's^2=\frac{(n_1-1)s_1^2+(n_2-1)s_2^2}{n_1+n_2-2}',r's_d=\sqrt{\frac{s^2}{n_1}+\frac{s^2}{n_2}},\quad \nu=n_1+n_2-2',r'(\bar x_1-\bar x_2)\pm t_\alpha(\nu)s_d'],example='ci-urine',shortcut=r'For equal group sizes, \(s^2=(s_1^2+s_2^2)/2\) and \(s_d=\sqrt{(s_1^2+s_2^2)/n}\). This shortens the same pooled calculation.'),
 dict(id='oneMean',title='One population mean → one-sample t interval',trigger='One group has a sample mean, sample SD, and sample size; estimate the population mean.',pages=[9,10],formula=[r's_{\bar x}=\frac{s}{\sqrt n},\quad \nu=n-1',r'\bar x\pm t_\alpha(\nu)s_{\bar x}'],example='ci-heart',shortcut='Compute SEM once, then margin once. Subtract and add the same margin around the sample mean.'),
 dict(id='twoProportions',title='Two event proportions → course pooled z interval',trigger='Two independent groups each have event counts and totals; estimate the difference in event probability.',pages=[11,12],formula=[r'\hat p_i=m_i/n_i,\quad \hat p=\frac{m_1+m_2}{n_1+n_2}',r's_d=\sqrt{\hat p(1-\hat p)\left(\frac1{n_1}+\frac1{n_2}\right)}',r'(\hat p_1-\hat p_2)\pm z_\alpha s_d'],example='ci-aspirin',shortcut='Keep the group proportions for the center and the pooled proportion for the SE. These have different jobs in the lecture formula.'),
 dict(id='oneProportion',title='One event proportion → Normal interval',trigger='One sample supplies an event count and total; estimate its population proportion.',pages=[13,14,15,16],formula=[r'\hat p=\frac mn,\quad s_{\hat p}=\sqrt{\frac{\hat p(1-\hat p)}n}',r'\hat p\pm z_\alpha s_{\hat p}'],example='ci-survey',shortcut='Convert count to proportion first. Work in proportion units until the final percentage interpretation.'),
 dict(id='decision',title='Use the interval to make a two-sided decision',trigger='A confidence interval is given and the question asks whether the null population value is supported.',pages=[8,15,17],formula=[r'\theta_0\in[L,U]\Rightarrow\text{do not reject }H_0',r'\theta_0\notin[L,U]\Rightarrow\text{reject }H_0'],example='ci-glucose',shortcut='Differences use a null of zero. One mean or one proportion uses the specific reference in the question. Match confidence and significance levels.')]
for method in methods:
 page=next(s for s in slides if s['page']==method['pages'][0]);method['paragraphs']=page['paragraphs'];method['symbols']=page['symbols']
questions=[]
def question(topic,stem,options,why,case=None,equations=()):
 questions.append(dict(id=f'm2-s17-q{len(questions)+1:03}',module=17,topic=topic,stem=stem,options=options,correct=0,why=why,case=case,equations=list(equations)))
# Each numerical checkpoint is attached to a complete clinical question and all its work.
for c in cases:
 v=c['values']
 for field,word in [('lower','lower endpoint'),('upper','upper endpoint'),('se','standard error')]:
  value=v[field];unit=c['unit'];scale=max(abs(v.get('margin',value))*.6,.015)
  wrong=[value+scale,value-scale,value+2*scale]
  options=[rf'\({f(x)}\) {unit}' for x in [value,*wrong]]
  chosen=next(st for st in c['steps'] if ('standard error' in st['title'].lower() or ' SE' in st['title']) ) if field=='se' else next(st for st in c['steps'] if ('lower' in st['title'].lower() if field=='lower' else 'upper' in st['title'].lower())) if any(('lower' if field=='lower' else 'upper') in st['title'].lower() for st in c['steps']) else next(st for st in c['steps'] if 'bounds' in st['title'].lower() or 'endpoints' in st['title'].lower())
  question(c['topic'],f'For the {c["title"].lower()} study, construct the requested {100*v["confidence"]:g}% interval using the stated course method. What is its {word}?',options,f'The {word} is {f(value)} {unit}. '+chosen['words'],c['id'],chosen['general']+chosen['work'])
concepts=[
('meaning','A procedure is used to construct a 95% interval from each of many new samples of the same populations. Which description gives its confidence meaning?', ['About 95% of these intervals contain the same true population quantity.','About 95% of individual observations must lie in every calculated interval.','The true population mean changes to match the center of each new interval.','Every particular interval is guaranteed to contain the parameter.'],'The population quantity is fixed, while random samples produce different intervals. Confidence describes repeated coverage of that procedure.'),
('meaning','A 95% interval estimates the mean heart rate as 60.6 to 73.4 beats/min. Which statement interprets the target of that interval?', ['It estimates the population mean heart rate, with 95% confidence in the interval procedure.','It contains 95% of all individual student heart rates.','It states that the sample mean has a 95% chance of changing from 67 to another value.','It estimates the SD of individual heart rates rather than their mean.'],'A confidence interval for a mean concerns the population average. Individual spread is measured separately by the SD.'),
('decision','A 95% interval for treatment minus control is −1.4 to 2.1 units. Which two-sided decision is justified at 0.05?', ['Do not reject equal population means because zero is included.','Reject equal population means because one endpoint is negative.','Conclude the population means are exactly equal.','Reject equal population means because the endpoints have different signs.'],'The difference interval spans zero, so it includes the equal-means null. Nonrejection does not establish exact equality.'),
('decision','A 95% interval for treatment minus control is −4.2 to −0.8 units. Which conclusion preserves its direction?', ['The treatment population mean is lower, and zero is excluded.','The treatment population mean is higher because the interval is statistically significant.','The population means are equal because both endpoints have the same sign.','No direction can be stated unless a separate t statistic is calculated.'],'Both bounds are negative for treatment minus control, placing the treatment mean below control. Zero exclusion gives the corresponding two-sided decision.'),
('decision','An interval for the population difference is 0 to 3.2 units. Applying the lecture’s includes-zero rule, what is the appropriate decision?', ['Do not reject the zero-difference null because zero is included at the endpoint.','Reject the null because the upper endpoint is positive.','Reject the null because zero must occur strictly inside the interval to count.','Conclude every individual benefits by exactly 3.2 units.'],'The stated rule concerns whether zero is included, including a boundary endpoint. It does not concern whether every individual changes.'),
('oneMean','A 95% CI for a mean is 60.6 to 73.4. The null specifies a population mean of 70. What value should be checked against the interval?', ['70, because it is the population mean specified by the null.','Zero, because every confidence-interval decision uses zero.','67, because the sample mean always replaces the null reference.','9, because the sample SD is the null population mean.'],'For a single mean, check the specified null mean. Zero is the usual null for a difference, not every parameter.'),
('oneProportion','A 95% interval for a population proportion is 0.312 to 0.396, and the null states p=0.5. Which conclusion follows?', ['Reject p=0.5; the compatible population proportions are below one half.','Do not reject p=0.5 because zero is not in the interval.','Conclude 95% of respondents have outcomes between 0.312 and 0.396.','Reject only if the interval is entirely negative.'],'The comparison is with 0.5, which is excluded above the upper endpoint. The interval concerns an event proportion, not the range of binary individual outcomes.'),
('twoMeans','Independent Normal samples with a common variance have sizes 12 and 16. Which df belongs to the pooled mean-difference interval?', ['26','27','11','15'],'The pooled two-sample df is n1+n2−2, giving 12+16−2=26.'),
('oneMean','A single independent Normal sample contains ten observations. Which df supplies the one-sample t confidence cutoff?', ['9','10','18','Infinity'],'The one-sample mean interval uses n−1 degrees of freedom, so ten observations give nine.'),
('meaning','For a 95% two-sided confidence interval, which left cumulative area gives the positive t cutoff?', ['0.975','0.95','0.025','0.05'],'The total excluded area is 0.05, with 0.025 in each tail. The positive cutoff therefore has 0.975 to its left.'),
('meaning','The supplied t table labels a column by total two-tail alpha. Which lookup corresponds to a 95% interval?', ['The 0.05 total two-tail column at the appropriate df.','The 0.025 total two-tail column after halving alpha again.','The 0.95 two-tail column because confidence is 95%.','Any df row because the t cutoff is always 1.96.'],'The course column already accounts for both tails. Halving alpha again selects a different confidence level.'),
('oneMean','The heart-rate sample SD is 9 beats/min and n=10. Which role belongs to 9 divided by the square root of 10?', ['The standard error of the sample mean.','The variance of individual heart rates.','The population mean specified by the null.','The full confidence-interval width.'],'Dividing SD by the root of sample size estimates variability of the sample mean. The margin also requires the critical value.'),
('twoMeans','Two groups have unequal sample sizes and SDs. Which operation follows the course pooled-variance formula?', ['Weight each squared SD by its own n−1, add, and divide by n1+n2−2.','Average the unsquared SDs and use that as the variance.','Weight the two means by their SDs and divide by n1+n2.','Use the larger SD as the common variance without squaring it.'],'The formula pools variance contributions, not SDs or means. The unequal group df determine their weights.'),
('twoMeans','For equal group sizes n, how can the pooled SE calculation be shortened without changing the method?', [r'Use \(s_d=\sqrt{(s_1^2+s_2^2)/n}\).',r'Use \(s_d=(s_1+s_2)/n\).',r'Use \(s_d=\sqrt{s_1+s_2}\).',r'Use \(s_d=s_1^2+s_2^2\).'],'Equal n makes the pooled variance the average of the two group variances; substituting it into the two-group SE gives the stated root.'),
('twoMeans','Which hypothesis statement describes a two-sided population mean comparison in words?', ['The null says the population means are equal, and the alternative says they differ.','The null says the observed sample means must be identical in every sample.','The alternative says the sample SDs are unequal, regardless of the means.','The null says a particular person has the group-average response.'],'The parameters being compared are population means. Sample means can differ under an equal-population-means null.'),
('twoProportions','The aspirin slide’s CI is approximately 0.11 to 0.69 for placebo minus aspirin. What kind of effect does this interval describe?', ['An absolute difference of about 11 to 69 percentage points.','A relative-risk reduction of exactly 11% to 69%.','The probability that a particular aspirin patient has an event.','The SD of the number of placebo events.'],'Subtracting proportions produces an absolute probability difference. A relative-risk reduction requires a ratio and is a different calculation.'),
('twoProportions','Which data are combined to form the pooled proportion in Session 17?', ['The event counts are added and divided by the sum of the group sizes.','The two sample proportions are averaged without regard to group size.','Only the larger sample’s event count is divided by both sample sizes.','The SDs of two continuous outcomes are averaged.'],'The pooled event fraction uses total events over total observations. An unweighted average of proportions can differ when group sizes differ.'),
('twoProportions','For the course two-proportion interval, which quantities supply the center and standard error?', ['Separate group proportions supply the center difference; the pooled proportion supplies the SE variance.','The pooled proportion supplies the center difference, which is always zero.','The pooled proportion is used only to decide which group is first.','The two proportions are replaced by sample means of continuous measurements.'],'The observed difference uses each group’s own event fraction. Session 17 uses the combined event fraction inside the binary variance for the SE.'),
('oneProportion','A binary sample contains 177 yes responses among 500 participants. Which expression estimates its standard error?', [r'\(\sqrt{(177/500)(1-177/500)/500}\)',r'\((177/500)(1-177/500)\)',r'\(177/\sqrt{500}\)',r'\(\sqrt{177/500}\)'],'Convert the count to a proportion, form p-hat times one minus p-hat, divide by n, then take the root.'),
('oneProportion','What does the null p=0.5 mean for the stimulant survey?', ['The population proportion reporting the behavior is one half.','Exactly half of every random sample must answer yes.','The observed sample proportion is defined to be one half.','Each student reports a response equal to 0.5 rather than yes or no.'],'The null concerns the population event proportion. The observed fraction is allowed to differ because a sample is random.'),
('meaning','The same data are used for 95% and 99% intervals with the same method. How do their widths compare?', ['The 99% interval is wider because its critical value is larger.','The 99% interval is narrower because confidence always removes uncertainty.','The widths are identical because the sample estimate is unchanged.','The 99% interval must have a different sample mean as its center.'],'The center and SE are unchanged, while greater confidence requires a larger critical multiple.'),
('oneMean','If sample size is multiplied by four while sample SD is held fixed, what happens to the standard error s/√n?', ['It is halved.','It is divided by four.','It doubles.','It stays unchanged.'],'The root of four times n is twice the root of n, so the same SD is divided by twice the denominator.'),
('meaning','An interval is written as estimate minus M to estimate plus M. What is its full width?', ['2M','M','M/2','The estimate itself'],'The upper endpoint minus the lower endpoint is (estimate+M)−(estimate−M)=2M.'),
('twoMeans','A placebo-minus-drug interval for glucose is 2.889 to 3.711 mg/dL. Which direction is supported?', ['The drug population mean is lower than the placebo population mean.','The drug population mean is higher because both bounds are positive.','Every drug recipient has a lower value than every placebo recipient.','The population means are equal because the interval has two endpoints.'],'Positive placebo-minus-drug values place the placebo mean above the drug mean. The parameter is a difference of population averages, not an ordering of all individuals.'),
('twoMeans','A mean-difference interval for group 1 minus group 2 is [2,5]. What interval expresses group 2 minus group 1?', ['[−5,−2]','[−2,−5]','[2,5]','[0,3]'],'Reversing the subtraction multiplies the difference by minus one and reverses the endpoint order. The zero-inclusion decision is unchanged.'),
('oneMean','A confidence interval for a population mean uses the sample SD because the population SD is unknown. Which distribution and df are used in this lecture?', ['t with n−1 df.','Always Normal with no role for sample size.','F with n numerator df and one denominator df.','Chi-square with twice the sample size.'],'The one-sample mean interval uses the t procedure with a sample-based SEM and n−1 df.'),
('twoProportions','The aspirin slide rounds 6/19 to 0.32 and the SE to 0.15. Why can a calculation retaining the fractions yield a slightly different upper endpoint?', ['The slide rounds intermediate quantities before calculating its margin and center.','The original fractions and the rounded values represent different patient counts.','A confidence level of 95% requires rounding all values to integers.','A positive endpoint forces the pooled proportion to equal 0.5.'],'Early rounding changes both the center difference and the margin slightly. Preserve the stated precision when reproducing a slide calculation.'),
('decision','A two-sided interval excludes its matching null value at 95% confidence. What significance level matches that decision?', ['0.05','0.95','0.025 after treating the interval as one-sided','0.50'],'The interval has confidence 1−alpha. A two-sided 95% interval matches alpha=0.05 for its associated procedure.'),
('meaning','Repeated intervals from one fixed population have different endpoints. Which quantity remains the same across the repeated samples?', ['The population parameter being estimated.','Every sample mean.','Every sample standard error.','The lower endpoint of every interval.'],'The parameter is a fixed population quantity. Sample statistics and the constructed interval endpoints can vary.'),
('oneProportion','A proportion interval is 0.28 to 0.36. How is the same interval expressed as percentages?', ['28% to 36%.','0.28% to 0.36%.','280% to 360%.','28 to 36 events regardless of sample size.'],'Multiplying each proportion by 100 converts it to a percentage. An event count additionally requires the relevant sample size.'),
('twoMeans','Which assumptions accompany the Session 17 pooled two-mean calculation?', ['Independent observations from Normal populations with a common variance.','A paired design is required and the two group sizes must always be identical.','The population variances must be known exactly before observing the samples.','Every individual response must equal the sample mean.'],'The lecture extends the pooled two-sample t framework. Equal group size is a shortcut condition, not the full method’s requirement.'),
('meaning','What happens to the t critical value as df becomes very large for a fixed 95% two-sided interval?', ['It approaches the Normal cutoff near 1.96.','It approaches zero.','It approaches the sample SD.','It becomes a probability greater than one.'],'The infinite-df row of the t table corresponds to the standard Normal cutoff used for the proportion intervals.'),
('decision','A two-sided CI includes a specified null mean. What can be concluded from the lecture’s rule?', ['The matching test does not reject that null; exact equality has not been proven.','The population mean is known to equal the null with certainty.','The sample has zero variability.','Every possible confidence level must include the same null value.'],'Inclusion means the procedure does not reject the reference at that level. Different confidence levels can produce different widths.'),
('oneProportion','A CI for p is centered at the observed p-hat. Which quantity is used inside its estimated variance in Session 17?', ['The observed sample proportion and its complement.','The null reference alone, regardless of the observed sample.','The event count without division by n.','The confidence percentage treated as an event count.'],'The stated one-proportion CI uses p-hat(1−p-hat)/n inside the root. Its center and estimated SE both use the sample proportion.')]
assert len(concepts)==34,len(concepts)
for topic,stem,options,why in concepts:
 stem=stem.replace('null p=0.5',r'null \(p=0.5\)').replace('null states p=0.5',r'null states \(p=0.5\)').replace('standard error s/√n','standard error of the sample mean')
 why=why.replace('The pooled two-sample df is n1+n2−2, giving 12+16−2=26.',r'The pooled two-sample degrees of freedom add the two group sizes and subtract two. \[\nu=n_1+n_2-2=12+16-2=26\]')
 why=why.replace('The one-sample mean interval uses n−1 degrees of freedom, so ten observations give nine.',r'The one-sample degrees of freedom are one less than the sample size. \[\nu=n-1=10-1=9\]')
 why=why.replace('The upper endpoint minus the lower endpoint is (estimate+M)−(estimate−M)=2M.',r'Subtracting the lower bound from the upper bound gives the full interval width. \[U-L=(\hat\theta+M)-(\hat\theta-M)=2M\]')
 why=why.replace('The stated one-proportion CI uses p-hat(1−p-hat)/n inside the root.',r'The stated one-proportion interval uses \[s_{\hat p}=\sqrt{\hat p(1-\hat p)/n}.\]')
 why=why.replace('alpha=0.05',r'\(\alpha=0.05\)')
 if stem.startswith('An interval is written'):options=[r'\(2M\)',r'\(M\)',r'\(M/2\)','The estimate itself']
 question(topic,stem,options,why)
assert len(questions)==100,len(questions)

